import { Component, TemplateRef, input } from '@angular/core';
import { NzPopoverDirective } from 'ng-zorro-antd/popover';

/** hrm-hover-card — rê chuột vào phần tử neo (tên nhân viên, mã đơn…) → hiện thẻ nổi
 *  xem nhanh (hồ sơ mini, tóm tắt đơn) mà không rời ngữ cảnh. Nội dung thẻ = TemplateRef
 *  bên gọi cấp. Bọc nz-popover trigger hover, delay nhẹ chống nháy khi lướt ngang. */
@Component({
  selector: 'hrm-hover-card',
  imports: [NzPopoverDirective],
  template: `
    <span
      class="hc-anchor"
      nz-popover
      nzPopoverTrigger="hover"
      [nzPopoverContent]="content() ?? undefined"
      [nzPopoverPlacement]="placement()"
      [nzPopoverMouseEnterDelay]="0.15"
      [nzPopoverMouseLeaveDelay]="0.1">
      <ng-content />
    </span>
  `,
  host: { class: 'hrm-hover-card' },
  styles: [`
:host { display: inline-flex; min-width: 0; }
.hc-anchor { display: inline-flex; min-width: 0; cursor: default; }
  `],
})
export class HrmHoverCard {
  /** Nội dung thẻ nổi (TemplateRef bên gọi cấp). */
  readonly content = input<TemplateRef<void> | null>(null);
  readonly placement = input<'top' | 'bottom' | 'left' | 'right' | 'topLeft' | 'bottomLeft'>('top');
}
